import * as T from './vendor/three.module.js';
import {ITEMS,addItem,isBagSlot} from './inventory.js';
import {respawnCheckpoint} from './respawn.js';
export function takeDeathLoss(p,slots,now,rand=Math.random){const fraction=p.lastDeathAt!==null&&p.lastDeathAt!==undefined&&now-p.lastDeathAt>=0&&now-p.lastDeathAt<=180?.5:.3;const xp=Math.ceil(p.xp*fraction);p.xp=Math.max(0,p.xp-xp);p.lastDeathAt=now;const gold=Math.floor((p.gold||0)*.6);p.gold=(p.gold||0)-gold;const pool=[];for(let i=6;i<slots.length;i++)if(isBagSlot(i)&&slots[i])pool.push({index:i,count:slots[i].count});const total=pool.reduce((sum,i)=>sum+i.count,0),amount=Math.ceil(total*.3),items=[];let remaining=total;for(let j=0;j<amount;j++){let pick=Math.min(remaining-1,Math.floor(rand()*remaining));const entry=pool.find(i=>{if(pick<i.count)return true;pick-=i.count;return false});const item=slots[entry.index],drop=items.find(i=>i.id===item.id);if(drop)drop.count++;else items.push({id:item.id,count:1});entry.count--;item.count--;remaining--;if(!item.count)slots[entry.index]=null}return {xp,fraction,gold,items}}
export function journey({scene,camera,p,slots,zone,time,site,travel,rand=Math.random}){
 const bags=[];let nextId=1;
 function visual(b){const root=new T.Group();root.position.fromArray(b.position);const sack=new T.Mesh(new T.SphereGeometry(.3,10,8),new T.MeshStandardMaterial({color:0x715239,emissive:0x51432a,emissiveIntensity:.7}));sack.scale.set(1,.8,.8);sack.position.y=.27;root.add(sack);const knot=new T.Mesh(new T.TorusGeometry(.1,.025,5,10),new T.MeshBasicMaterial({color:0xffd68b}));knot.position.y=.48;knot.rotation.x=Math.PI/2;root.add(knot);const light=new T.PointLight(0xf4c36b,3,4,2);light.position.y=.6;root.add(light);scene.add(root);b.g=root;bags.push(b);return b}
 function clear(){for(const b of bags){b.g.removeFromParent();b.g.traverse(o=>{o.geometry?.dispose();if(o.material)o.material.dispose()})}bags.length=0}
 function died(){clear();const loss=takeDeathLoss(p,slots,time(),rand),pos=site();if(loss.gold||loss.items.length)visual({id:nextId++,zone:pos.zone,position:[pos.position[0],0,pos.position[2]],gold:loss.gold,items:loss.items});return loss}
 function near(){return bags.find(b=>b.zone===zone()&&Math.hypot(camera.position.x-b.position[0],camera.position.z-b.position[2])<2)}
 function take(b,index){if(!bags.includes(b)||!b.items[index])return false;const item=b.items[index];const limited=['mary_ale','return_bone'].includes(item.id),held=slots.reduce((s,i)=>s+(i?.id===item.id?i.count:0),0),amount=limited?Math.min(item.count,Math.max(0,(item.id==='mary_ale'?12:3)-held)):item.count;if(!amount||!addItem(slots,item.id,amount))return false;item.count-=amount;if(!item.count)b.items.splice(index,1);return true}
 function collectGold(b){if(!bags.includes(b))return;p.gold+=b.gold;b.gold=0}
 function finish(b){if(b.gold||b.items.length)return;const i=bags.indexOf(b);if(i<0)return;b.g.removeFromParent();b.g.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});bags.splice(i,1)}
 return {bags,died,near,take,collectGold,finish,checkpoint:()=>respawnCheckpoint(p),returnToCheckpoint(){return travel(respawnCheckpoint(p))},tick(){for(const b of bags){b.g.visible=b.zone===zone();b.g.rotation.y=Math.sin(time()*.7+b.id)*.08}},snapshot:()=>({nextId,bags:bags.map(({g,...b})=>({...b,position:[...b.position],items:b.items.map(i=>({...i}))}))}),restore(s){clear();nextId=s?.nextId||1;for(const b of (s?.bags||[]).slice(-1))visual({...b,position:[...b.position],items:b.items.map(i=>({...i}))})}};
}
